  "news.pro.confirm_hard_label": { fa: "حذف ردیف‌های IRRELEVANT", de: "IRRELEVANT-Zeilen löschen", es: "Eliminar filas IRRELEVANT", ar: "حذف صفوف IRRELEVANT" },
  "news.pro.confirm_soft_label": { fa: "شمارش کاندیداها", de: "Kandidaten zählen", es: "Contar candidatos", ar: "عدّ المرشحين" },
  "news.pro.confirm_prune_label": { fa: "غیرمرتبط را IRRELEVANT علامت بزن", de: "Unrelatiertes als IRRELEVANT markieren", es: "Marcar lo no relacionado como IRRELEVANT", ar: "تعليم غير ذي الصلة بـ IRRELEVANT" },
  "news.pro.cycle_body_1": { fa: "اجرای همان ", de: "Führt denselben ", es: "Ejecuta el mismo ", ar: "يشغّل نفس " },
  "news.pro.cycle_body_2": { fa: " را به کار می‌گیرد: هر مقاله تحلیل‌نشده را تحلیل می‌کند (اول طلا، سقف 200 در هر فشردن) و سپس ناخواسته‌ها را می‌برد. پشتیبان یک ", de: " aus, den der Worker nutzt: analysiert jeden unanalysierten Artikel (Gold zuerst, Limit 200 pro Druck) und trimmt dann Müll. Das Backend erzwingt eine ", es: " que usa el worker: analiza cada artículo no analizado (primero oro, límite 200 por pulsación) y poda la basura. El backend impone un ", ar: " الذي يستخدمه العامل: يحلّل كل مقال غير محلل (الذهب أولًا، حد 200 لكل ضغطة) ثم يتقلم المهمل. يفرض الخادم " },
  "news.pro.cycle_cooldown": { fa: "وقفه 15 ثانیه‌ای", de: "15s-Sperre", es: "enfriamiento de 15 s", ar: "تأخير 15 ثانية" },
  "news.pro.cycle_body_3": { fa: " میان تخلیه‌ها — فشردن ردشده کد COOLDOWN را عیناً نشان می‌دهد. پیشرفت در ردیاب کنسول دیده می‌شود، نه یک نوار ساختگی.", de: " zwischen den Drains — ein abgewiesener Druck zeigt den COOLDOWN-Code wörtlich. Fortschritt erscheint im Konsolen-Trace, nie als Fake-Balken.", es: " entre drenajes: una pulsación rechazada muestra el código COOLDOWN textualmente. El progreso aparece en la traza de la consola, nunca como barra falsa.", ar: " بين عمليات التصفية — الضغط المرفوض يعرض رمز COOLDOWN حرفيًا. يظهر التقدم في أثر الكونسول لا كشريط وهمي." },
  "news.pro.soft_body_1": { fa: "گزارش می‌دهد چند ", de: "Berichtet, wie viele ", es: "Informa de cuántas ", ar: "يبلغ عن عدد " },
  "news.pro.soft_body_2": { fa: " ردیف IRRELEVANT وجود دارد و چند مورد داخل پنجره محدود (5000) است. ", de: " IRRELEVANT-Zeilen existieren und wie viele im Limit-Fenster (5000) liegen. ", es: " filas IRRELEVANT existen y cuántas caen en la ventana de límite (5000). ", ar: " صف IRRELEVANT موجود وكم منها داخل نافذة الحد (5000). " },
  "news.pro.soft_body_3": { fa: "چیزی حذف نمی‌شود", de: "Nichts wird gelöscht", es: "No se elimina nada", ar: "لا يُحذف شيء" },
  "news.pro.soft_body_4": { fa: " با پاک‌سازی نرم.", de: " durch einen Soft-Purge.", es: " con una purga suave.", ar: " بالتنظيف الناعم." },
  "news.pro.hard_body_1": { fa: "حذف قطعی", de: "HARD DELETE", es: "ELIMINACIÓN IRREVERSIBLE", ar: "حذف نهائي" },
  "news.pro.hard_body_2": { fa: ": تا 5000 مقاله IRRELEVANT و ردیف‌های مشتق از آنها (تحلیل، پاسخ‌های هوش مصنوعی، موجودیت‌ها، موضوعات، تأثیرات، اجماع) را از پایگاه داده اخبار حذف می‌کند. ", de: ": entfernt bis zu 5000 IRRELEVANT-Artikel und ihre abgeleiteten Zeilen (Analyse, KI-Antworten, Entitäten, Themen, Impacts, Konsens) aus der News-DB. ", es: ": elimina hasta 5000 artículos IRRELEVANT y sus filas derivadas (análisis, respuestas de IA, entidades, temas, impactos, consenso) de la base de noticias. ", ar: ": يحذف حتى 5000 مقال IRRELEVANT وصفوفها المشتقة (التحليل، إجابات الذكاء الاصطناعي، الكيانات، المواضيع، التأثيرات، الإجماع) من قاعدة بيانات الأخبار. " },
  "news.pro.hard_body_3": { fa: "این عمل قابل بازگشت نیست.", de: "Dies kann nicht rückgängig gemacht werden.", es: "Esto no se puede deshacer.", ar: "لا يمكن التراجع عن هذا." },
  "news.pro.prune_body_1": { fa: "داستان‌های کم‌اهمیت / غیر-XAUUSD را علامت می‌زند ", de: "Markiert unwichtige / nicht-XAUUSD-Geschichten ", es: "Marca historias de baja importancia / no XAUUSD ", ar: "يعلّم القصص منخفضة الأهمية / غير XAUUSD " },
  "news.pro.prune_body_2": { fa: " با اهمیت + ارتباط — اصل‌ها حفظ و از فیلتر بی‌ربط قابل بازیابی می‌مانند. idempotent: اجرای دوباره چیزی را تغییر نمی‌دهد.", de: " nach Bedeutung + Relevanz — Originale bleiben erhalten und über den Irrelevant-Filter wiederherstellbar. Idempotent: ein zweiter Lauf ändert nichts.", es: " según importancia + relevancia: los originales se conservan y quedan recuperables con el filtro Irrelevante. Idempotente: un segundo paso no cambia nada.", ar: " حسب الأهمية والارتباط — تبقى الأصول محفوظة وقابلة للاسترجاع عبر فلتر «غير ذي صلة». قابل للتكرار: التمريرة الثانية لا تغيّر شيئًا." },
